<body>
<div id="app">
<header>
  <div class="logo">● <span>Pomofocus</span></div>
  <div class="header-actions">
    <button class="btn icon-btn" title="Reports">▥</button>
    <button class="btn icon-btn" title="Settings">⚙</button>
    <button class="btn icon-btn" title="Profile">●</button>
    <button class="btn icon-btn more" id="headerMore">⋮</button>
  </div>
</header>

<section class="timer-card">
  <div class="modes">
    <button class="btn mode active" data-mode="pomodoro">Pomodoro</button>
    <button class="btn mode" data-mode="short">Short Break</button>
    <button class="btn mode" data-mode="long">Long Break</button>
  </div>
  <div class="time" id="time">25:00</div>
  <div class="running-row">
    <button class="btn start" id="startBtn">START</button>
    <button class="btn skip" id="skipBtn" style="display:none">▶|</button>
  </div>
</section>

<div class="session">
  <div class="session-number">#1</div>
  <div class="session-name" id="sessionName">Time to focus!</div>
</div>

<section class="tasks">
  <div class="tasks-head">
    <h2>Tasks</h2>
    <button class="btn icon-btn" id="taskMore">⋮</button>
  </div>
  <div id="taskList"></div>
  <button class="btn add-task" id="addTask"><span>⊕</span> Add Task</button>
  <div id="summary" class="summary" style="display:none">
    <span>Pomos: <strong id="pomos">0 / 1</strong></span>
    <span>Finish At: <strong id="finish">14:57</strong> <small>(0.4h)</small></span>
  </div>
</section>
<div class="menu-pop" id="menuPop">
  <div class="btn">Clear finished tasks</div>
  <div class="btn">Clear act pomodoros</div>
  <div class="btn">Save as routine</div>
  <div class="btn">Add from routines</div>
</div>
</div>

<section class="info">
  <h1>An online Pomodoro Timer to boost<br>your productivity</h1>
  <h2>What is Pomofocus?</h2>
  <div class="underline"></div>
  <p>Pomofocus is a customizable pomodoro timer that works on desktop &amp; mobile browser. The aim of this app is to help you focus on any task you are working on, such as study, writing, or coding. This app is inspired by <b>Pomodoro Technique</b> which is a time management method developed by Francesco Cirillo.</p>
</section>

<script>
const modes={
 pomodoro:{time:1500,name:'Time to focus!'},
 short:{time:300,name:'Time for a break!'},
 long:{time:900,name:'Time for a break!'}
};
let current='pomodoro', remaining=1500, timer=null, running=false, tasks=[];
const app=document.getElementById('app'), timeEl=document.getElementById('time');
const startBtn=document.getElementById('startBtn'), skipBtn=document.getElementById('skipBtn');
const sessionName=document.getElementById('sessionName'), taskList=document.getElementById('taskList');
const summary=document.getElementById('summary');

function format(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')}
function renderTime(){timeEl.textContent=format(remaining)}
function selectMode(mode){
 current=mode; remaining=modes[mode].time; running=false; clearInterval(timer);
 document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode===mode));
 sessionName.textContent=modes[mode].name; startBtn.textContent='START'; skipBtn.style.display='none'; renderTime();
}
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>selectMode(b.dataset.mode));
startBtn.onclick=()=>{
 running=!running;
 if(running){
   startBtn.textContent='PAUSE'; skipBtn.style.display='block';
   timer=setInterval(()=>{if(remaining>0){remaining--;renderTime()}else{running=false;clearInterval(timer);startBtn.textContent='START'}},1000);
 }else{clearInterval(timer);startBtn.textContent='START';skipBtn.style.display='none'}
};
skipBtn.onclick=()=>{remaining=0;renderTime();startBtn.click()};
function editor(){
 const wrap=document.createElement('div'); wrap.className='task-editor';
 wrap.innerHTML=`<div class="editor-body">
  <input class="task-input" placeholder="What are you working on?" maxlength="80">
  <div class="editor-label">Est Pomodoros</div>
  <div class="est-row"><div class="est-number">1</div><button class="btn arrow">▲</button><button class="btn arrow">▼</button></div>
  <div class="editor-links"><span class="btn">+ Add Note</span>&nbsp;&nbsp; <span class="btn">+ Add Project</span> <span class="lock">▣</span></div>
 </div>
 <div class="editor-actions"><span class="btn cancel">Cancel</span><button class="btn save">Save</button></div>`;
 wrap.querySelector('.cancel').onclick=()=>wrap.remove();
 wrap.querySelector('.save').onclick=()=>{
   const val=wrap.querySelector('.task-input').value.trim();
   if(!val)return;
   tasks.push({title:val,done:false}); renderTasks();
   wrap.remove(); addEditor(false);
 };
 return wrap;
}
function addEditor(scroll=true){
 const ed=editor(); taskList.appendChild(ed);
 if(scroll)setTimeout(()=>window.scrollTo({top:450,behavior:'instant'}),30);
 ed.querySelector('.task-input').focus();
}
function renderTasks(){
 taskList.innerHTML='';
 tasks.forEach((t,i)=>{
   const row=document.createElement('div'); row.className='task-row '+(t.done?'done':'');
   row.innerHTML=`<button class="btn check">${t.done?'✓':''}</button><span class="task-title">${t.title}</span><span class="task-counter">0 / 1</span><button class="btn task-menu">⋮</button>`;
   row.querySelector('.check').onclick=()=>{t.done=!t.done;renderTasks(); if(t.done&&tasks.every(x=>x.done)) showToast()};
   taskList.appendChild(row);
 });
 if(tasks.length){document.getElementById('addTask').style.display='flex';summary.style.display='flex'}
 else summary.style.display='none';
}
document.getElementById('addTask').onclick=()=>addEditor(true);
document.getElementById('taskMore').onclick=()=>{const m=document.getElementById('menuPop');m.style.display=m.style.display==='block'?'none':'block'};
document.getElementById('headerMore').onclick=()=>{window.scrollTo({top:0,behavior:'instant'});document.getElementById('menuPop').style.display='none'};
function showToast(){
 const old=document.querySelector('.finish-toast');if(old)old.remove();
 const t=document.createElement('div');t.className='finish-toast';
 t.innerHTML=`<span>You've finished all your tasks for<br>today 🎉</span><button class="btn clear">Clear Tasks</button>`;
 t.querySelector('.clear').onclick=()=>{tasks=[];renderTasks();t.remove()};
 document.body.appendChild(t);
}
renderTime();
</script>
</body>
</html>
